import{_ as a,c as i,o as s,a3 as t}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/installation.md","filePath":"fr/guide/installation.md","lastUpdated":1787284674000}'),r={name:"fr/guide/installation.md"};function o(l,e,n,p,u,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>ClipboxAI est disponible pour macOS.</p><h2 id="options-de-telechargement" tabindex="-1">Options de téléchargement <a class="header-anchor" href="#options-de-telechargement" aria-label="Permalink to &quot;Options de téléchargement&quot;">​</a></h2><h3 id="mac-app-store-recommande" tabindex="-1">Mac App Store (recommandé) <a class="header-anchor" href="#mac-app-store-recommande" aria-label="Permalink to &quot;Mac App Store (recommandé)&quot;">​</a></h3><ul><li><strong>Téléchargement</strong> : recherchez <strong>ClipboxAI</strong> sur le Mac App Store, ou ouvrez le lien depuis la <a href="/fr/">page d&#39;accueil</a>.</li><li>La version du Mac App Store propose des mises à jour automatiques et une intégration macOS transparente.</li></ul><blockquote><p><s>Si un lien vers le Mac App Store n&#39;est pas encore disponible, utilisez la version GitHub Releases ci-dessous.</s></p></blockquote><h3 id="github-releases-alternative-pas-disponible-pour-l-instant" tabindex="-1"><s>GitHub Releases (alternative)</s> (pas disponible pour l&#39;instant) <a class="header-anchor" href="#github-releases-alternative-pas-disponible-pour-l-instant" aria-label="Permalink to &quot;~~GitHub Releases (alternative)~~ (pas disponible pour l&#39;instant)&quot;">​</a></h3><p><s>Vous pouvez télécharger la dernière version directement depuis <a href="https://github.com/clipboxAI" target="_blank" rel="noreferrer">GitHub Releases</a>. Notez que cette version ne reçoit pas de mises à jour automatiques.</s></p><h2 id="etapes-d-installation" tabindex="-1">Étapes d&#39;installation <a class="header-anchor" href="#etapes-d-installation" aria-label="Permalink to &quot;Étapes d&#39;installation&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>Ouvrez le lien de téléchargement ci-dessus ou recherchez « ClipboxAI » dans le Mac App Store.</li><li>Cliquez sur <strong>Obtenir</strong> pour télécharger l&#39;application.</li><li>L&#39;application s&#39;installe automatiquement — lancez-la depuis <strong>Applications</strong> ou <strong>Launchpad</strong>.</li></ol><h3 id="github-releases" tabindex="-1"><s>GitHub Releases</s> <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;~~GitHub Releases~~&quot;">​</a></h3><ol><li><s>Téléchargez le dernier fichier <code>.dmg</code> depuis la page Releases.</s></li><li><s>Double-cliquez sur le fichier <code>.dmg</code> téléchargé pour l&#39;ouvrir.</s></li><li><s>Glissez l&#39;icône <code>ClipboxAI.app</code> dans votre dossier <strong>Applications</strong>.</s></li><li><s>Éjectez l&#39;image montée et ouvrez l&#39;application depuis <strong>Applications</strong>.</s></li></ol><p>Si macOS empêche l&#39;ouverture de l&#39;application (Gatekeeper), ouvrez <strong>Réglages système → Confidentialité et sécurité</strong> et cliquez sur <strong>Ouvrir quand même</strong>, ou faites un clic droit sur l&#39;application et choisissez <strong>Ouvrir</strong>.</p><h2 id="premier-lancement" tabindex="-1">Premier lancement <a class="header-anchor" href="#premier-lancement" aria-label="Permalink to &quot;Premier lancement&quot;">​</a></h2><p>Au premier lancement, ClipboxAI vous guide à travers une courte configuration :</p><ul><li><strong>Activer l&#39;élément de la barre de menus</strong> pour que l&#39;application réside dans votre barre de menus.</li><li><strong>Accorder les permissions</strong> dont elle a besoin pour surveiller le presse-papiers en arrière-plan (voir <a href="/fr/guide/permissions.html">Permissions</a>).</li><li><em>(Facultatif)</em> <strong>Connecter un fournisseur d&#39;IA cloud</strong> dans <strong>Réglages → IA</strong> si vous souhaitez des actions IA.</li></ul><p>Accordez les permissions lorsque vous y êtes invité. Vous pouvez les modifier à tout moment dans <strong>Réglages système → Confidentialité et sécurité</strong>.</p><h2 id="mises-a-jour" tabindex="-1">Mises à jour <a class="header-anchor" href="#mises-a-jour" aria-label="Permalink to &quot;Mises à jour&quot;">​</a></h2><ul><li><strong>Version Mac App Store</strong> : mise à jour automatiquement par l&#39;App Store.</li><li><s><strong>Version GitHub Releases</strong> : téléchargez la version plus récente et remplacez l&#39;application dans <code>Applications</code>.</s></li></ul><h2 id="desinstallation" tabindex="-1">Désinstallation <a class="header-anchor" href="#desinstallation" aria-label="Permalink to &quot;Désinstallation&quot;">​</a></h2><p>Pour supprimer ClipboxAI :</p><ol><li>Quittez l&#39;application.</li><li>Glissez <code>ClipboxAI.app</code> de <code>Applications</code> vers la Corbeille.</li><li>(Facultatif) Supprimez les données locales :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Scripts/com.w3cub.clipboard</span></span></code></pre></div><h2 id="configuration-requise" tabindex="-1">Configuration requise <a class="header-anchor" href="#configuration-requise" aria-label="Permalink to &quot;Configuration requise&quot;">​</a></h2><ul><li><strong>macOS</strong> : Sonoma (14) ou version ultérieure</li><li><strong>Processeur</strong> : Apple Silicon (série M) ou Intel (64 bits)</li><li><strong>Mémoire</strong> : 4 Go minimum, 8 Go recommandés</li><li><strong>Stockage</strong> : ~50 Mo</li></ul><h2 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to &quot;Dépannage&quot;">​</a></h2><p>Si vous rencontrez des problèmes lors de l&#39;installation :</p><ul><li><strong>macOS bloque l&#39;application</strong> : ouvrez <strong>Réglages système → Confidentialité et sécurité</strong> et cliquez sur <strong>Ouvrir quand même</strong>.</li><li><strong>Avertissement de notarisation</strong> : téléchargez une version signée/notariée depuis le Mac App Store.</li></ul><p>Pour plus d&#39;aide, consultez le <a href="/fr/guide/troubleshooting.html">guide de dépannage</a>.</p>`,30)])])}const g=a(r,[["render",o]]);export{h as __pageData,g as default};
